function minimumOperations(nums) {
  let cost1 = 0;
  let cost2 = 0;
  let cost3 = 0;

  for (const value of nums) {
    const next1 = cost1 + (value === 1 ? 0 : 1);
    const next2 = Math.min(cost1, cost2) + (value === 2 ? 0 : 1);
    const next3 = Math.min(cost1, cost2, cost3) + (value === 3 ? 0 : 1);
    cost1 = next1;
    cost2 = next2;
    cost3 = next3;
  }
  return Math.min(cost1, cost2, cost3);
}

