function minimumOperations(nums) {
  const n = nums.length;
  let best = n;
  for (let i = 0; i <= n; i++) {
    for (let j = i; j <= n; j++) {
      let removed = 0;
      for (let k = 0; k < n; k++) {
        const wanted = k < i ? 1 : k < j ? 2 : 3;
        if (nums[k] !== wanted) removed++;
      }
      best = Math.min(best, removed);
    }
  }
  return best;
}

