function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 9);
  const style = Math.floor(rand() * 3);
  if (style === 0) {
    return [Array.from({ length: n }, () => 1 + Math.floor(rand() * 3))];
  }
  // Mostly sorted, with a few values out of place, so the answer is small but not zero.
  const nums = Array.from({ length: n }, (_, k) => 1 + Math.floor((3 * k) / n));
  const swaps = style === 1 ? Math.floor(rand() * 4) : Math.floor(rand() * n);
  for (let s = 0; s < swaps; s++) {
    const at = Math.floor(rand() * n);
    nums[at] = 1 + Math.floor(rand() * 3);
  }
  return [nums];
}
